139.         requires
140.             self.inv(),
141.             spec_frame_number(self@) <= spec_max_frame_number(),
142.         ensures
143.             spec_frame_raw_value(result) == spec_frame_number(self@),
144.             spec_from_number(spec_frame_raw_value(result)) == self@,
145.     )]
