2. 
3. use vstd::arithmetic::div_mod::lemma_mod_multiples_basic;
4. use vstd::arithmetic::div_mod::lemma_fundamental_div_mod;
5. 
6. // =================================================================================================
7. // Proof obligations for `FrameAddress`'s frame-number conversions.
8. //
9. // Both facts are elementary divisibility properties of `spec_page_size()`, which is the concrete
10. // architectural page size (4096) and therefore strictly positive.
11. // =================================================================================================
12. 
13. // `frame_index * PAGE_SIZE` is a multiple of `PAGE_SIZE`, hence page-aligned. Used by
14. // `from_frame_number` to discharge `PageAligned::from_address`'s alignment success condition.
15. pub proof fn lemma_frame_base_aligned(frame: FrameNumber)
16.     ensures
17.         spec_from_number(spec_frame_raw_value(frame)) % spec_page_size() == 0,
18. {
19.     assert(spec_page_size() > 0);
20.     lemma_mod_multiples_basic(spec_frame_raw_value(frame), spec_page_size());
21. }
22. 
23. // For a page-aligned address, dividing by `PAGE_SIZE` then multiplying recovers the address
24. // exactly. Used by `into_frame_number` to relate the recovered frame number back to `self@`.
25. pub proof fn lemma_aligned_div_mul(addr: int)
26.     requires
27.         addr % spec_page_size() == 0,
28.     ensures
29.         spec_from_number(spec_frame_number(addr)) == addr,
30. {
31.     assert(spec_page_size() > 0);
32.     lemma_fundamental_div_mod(addr, spec_page_size());
33. }
34. 
35. } // verus!
36.

